#include "nui_whale.h"

#include "nui_ui.h"

static uint16_t wh_color(char ch)
{
    switch (ch) {
    case 'O': return 0x1907;
    case 'k': return 0x218A;
    case 'd': return 0x2A0F;
    case 'b': return 0x32B3;
    case 'm': return 0x4B97;
    case 'l': return 0x7D9D;
    case 'c': return 0xAEDF;
    case 'w': return 0xEF5D;
    case 'g': return 0xCE9B;
    case 's': return 0xEEDA;
    case 'p': return 0xF598;
    case 'y': return 0xE60E;
    default:  return 0;
    }
}

uint16_t nui_whale_cyan(void)  { return 0x7D9D; }
uint16_t nui_whale_deep(void)  { return 0x2A0F; }
uint16_t nui_whale_light(void) { return 0xAEDF; }

