static const char *const *const WHALE_FRAME[NUI_WHALE_FRAMES] = {
    WHALE_F0, WHALE_F1,
};

void nui_whale_row(uint16_t *row, int sy, int ox, int oy, int frame)
{
    if (!row) return;
    if (frame < 0 || frame >= NUI_WHALE_FRAMES) frame = 0;

    const int s = NUI_WHALE_SCALE;
    if (sy < oy || sy >= oy + NUI_WHALE_N * s) return;

    const int r = (sy - oy) / s;
    const char *p = WHALE_FRAME[frame][r];

    int c = 0;
    while (c < NUI_WHALE_N && p[c]) {
        const char ch = p[c];
        int c2 = c;
        while (c2 + 1 < NUI_WHALE_N && p[c2 + 1] == ch) c2++;
        if (ch != '.') {
            const uint16_t col = wh_color(ch);
            if (col) nui_hspan(row, ox + c * s, ox + (c2 + 1) * s, col);
        }
        c = c2 + 1;
    }
}
